        pl = torch.tensor([arousal_low[s] for s in states])[si]
        pyro.sample("arousal", dist.Categorical(torch.stack([pl, 1 - pl], -1)))
        pyro.factor("meaning", torch.log(sem[si]))  # condition on literal meaning
        return si

    marg = _elbo().compute_marginals(model, lambda: None)
    _LL_CACHE[key] = marg
    return marg

def qud_answer(goal, state, valence, arousal):
    if goal == "goalState":
        return ("state", state)
    if goal == "goalValence":
        return ("valence", valence)
    return ("arousal", arousal)

def ll_logp_qud(utterance, goal, ans):
    marg = literal_listener_marginals(utterance, goal)
    kind, val = ans
    if kind == "state":
        d = marg["state"]; idx = states.index(val)
    elif kind == "valence":
        d = marg["valence"]; idx = valence_labels.index(val)
    else:
        d = marg["arousal"]; idx = arousal_labels.index(val)
    return float(d.log_prob(torch.tensor(idx)))

def ll_state_expectation(utterance, goal):
    d = literal_listener_marginals(utterance, goal)["state"]
    sup = d.enumerate_support()
    p = torch.exp(d.log_prob(sup))
    return float(sum(lam * states[int(i)] * float(pp) for i, pp in zip(sup, p)))

