# False cognates: nested RSA (literal listener -> speaker -> pragmatic
# listener) over a deterministic Spanish-translation step. Each level is a
# separate, completely-finished exact enumeration (config_enumerate +
# TraceEnum_ELBO.compute_marginals), memoized, feeding forward as a fixed
# score table. Site names are unique across levels (s0 / u1 / sc2).

states = [{"pregnant": 1, "embarrassed": 0}, {"pregnant": 0, "embarrassed": 1}]
state_probs = torch.tensor([0.4, 0.6])
utterances = ["pregnant", "embarrassed"]
competences = ["high", "low"]
NEG = torch.tensor(float("-inf"))
ZERO = torch.tensor(0.0)


def meaning(state, utterance):
    return state["pregnant"] == 1 if utterance == "pregnant" else state["embarrassed"] == 1


def bigrams(word):
    return [word[i:i + 2] for i in range(len(word) - 1)]


def similarity(word1, word2):
    b1, b2 = bigrams(word1), bigrams(word2)
    shared = [bg for bg in b1 if bg in b2]
    return (2 * len(shared)) / (len(b1) + len(b2))


def translate(utterance, competence):
    if utterance == "embarrassed" and competence == "high":
        return "avergonzada"
    if utterance == "embarrassed" and competence == "low":
        return ("embarazada" if similarity("embarazada", "embarrassed") >
                similarity("avergonzada", "embarrassed") else "avergonzada")
    if utterance == "pregnant" and competence == "high":
        return "embarazada"
    return ("avergonzada" if similarity("avergonzada", "pregnant") >
            similarity("embarazada", "pregnant") else "embarazada")


# Literal listener: posterior over state given the English utterance, inferred.
def literal_listener(utterance):
    @pyro.infer.config_enumerate
    def model():
        s = pyro.sample("s0", dist.Categorical(state_probs))
        ok = torch.tensor([meaning(states[i], utterance) for i in range(2)])
        pyro.factor("ev", torch.where(ok[s], ZERO, NEG))
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["s0"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    out = {0: 0.0, 1: 0.0}
    for i, p in zip(sup.tolist(), pr.tolist()):
        out[int(i)] = p
    return out


# Speaker: infers the English utterance given the true state, inferred, then
# deterministically translates it -> distribution over the Spanish word.
def speaker_translation_probs(state_idx, competence):
    l0 = {u: literal_listener(u) for u in utterances}

    @pyro.infer.config_enumerate
    def model():
        u = pyro.sample("u1", dist.Categorical(torch.ones(2)))
        sc = torch.tensor([
            math.log(l0[utterances[ui]][state_idx]) if l0[utterances[ui]][state_idx] > 0 else -1e30
            for ui in range(2)
        ])
        pyro.factor("sc", sc[u])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["u1"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    utt_probs = {0: 0.0, 1: 0.0}
    for i, p in zip(sup.tolist(), pr.tolist()):
        utt_probs[int(i)] = p

    out = defaultdict(float)
    for ui, p in utt_probs.items():
        out[translate(utterances[ui], competence)] += p
    return out


# Pragmatic listener: joint posterior over (state, competence) via a single
# combined enumerated latent, given the heard Spanish word.
def pragmatic_listener(translation):
    combos = [(s, c) for s in range(2) for c in range(2)]
    score_flat = torch.zeros(len(combos))
    joint_prior = torch.zeros(len(combos))
    for j, (si, ci) in enumerate(combos):
        sp = speaker_translation_probs(si, competences[ci])
        p = sp.get(translation, 0.0)
        score_flat[j] = math.log(p) if p > 0 else -1e30
        joint_prior[j] = state_probs[si].item() * 0.5

    @pyro.infer.config_enumerate
    def model():
        sc = pyro.sample("sc2", dist.Categorical(joint_prior))
        pyro.factor("obs", score_flat[sc])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["sc2"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    out = {}
    for i, p in zip(sup.tolist(), pr.tolist()):
        si, ci = combos[int(i)]
        rec = {"meant_pregnant": states[si]["pregnant"] == 1, "competence": competences[ci]}
        out[json.dumps(rec, sort_keys=True)] = p
    return out


