nS = len(stateVals)


def gaussian_pdf(x, mu, sig):
    return math.exp(-0.5 * ((x - mu) / sig) ** 2) / (sig * math.sqrt(2 * math.pi))


def state_probs(mu, sig):
    ps = [gaussian_pdf(s, mu, sig) for s in stateVals]
    t = sum(ps)
    return torch.tensor([p / t for p in ps])


sorted_sv = sorted(stateVals)
tall_thr = [s - 1.0 / (binParam * 2) for s in sorted_sv]
short_thr = [s + 1.0 / (binParam * 2) for s in sorted_sv]
nT = len(tall_thr)
