    mask = torch.tensor([0.0 if meaning(utterances[ui], stateVals[s], tall_thr[ti], short_thr[shi])
                         else -1e30 for s in range(nS)])

    @pyro.infer.config_enumerate
    def model():
        st = pyro.sample("st", dist.Categorical(sp))
        pyro.factor("cond", mask[st])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["st"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    out = [0.0] * nS
    for i, p in zip(sup.tolist(), pr.tolist()):
        out[int(i)] = p
    return out


def pragmatic_listener(ui):
    sub_sp = state_probs(sub_mu, sub_sigma)
    # L0 table, cached per (class, thresholds): each level genuinely inferred.
    ll = {}
    for ci in range(2):
        for ti in range(nT):
            for shi in range(nT):
                ll[(ci, ti, shi)] = [literal_listener(u, ti, shi, ci) for u in range(3)]

    # Speaker (S1): utterance posterior given (state, thresholds, class), inferred.
    score = torch.full((2, nS, nT, nT), -1e30)
    for ci in range(2):
        for ti in range(nT):
            for shi in range(nT):
                l0 = ll[(ci, ti, shi)]
                for si in range(nS):
                    sc = torch.tensor([alpha * (math.log(l0[u][si]) if l0[u][si] > 0 else -1e30)
                                       for u in range(3)])

                    @pyro.infer.config_enumerate
                    def smodel():
                        u = pyro.sample("u", dist.Categorical(torch.ones(3)))
                        pyro.factor("sc", sc[u])
                        return None

                    sm = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(smodel, lambda: None)
                    mm = sm["u"]
                    ssup = mm.enumerate_support()
                    spr = mm.log_prob(ssup).exp()
                    for i, p in zip(ssup.tolist(), spr.tolist()):
                        if int(i) == ui:
                            score[ci, si, ti, shi] = math.log(p) if p > 0 else -1e30

    # Pragmatic listener (L1): comparison-class marginal, inferred by enumeration.
    @pyro.infer.config_enumerate
    def model():
        st = pyro.sample("st", dist.Categorical(sub_sp))
        tt = pyro.sample("tt", dist.Categorical(torch.ones(nT)))
        sh = pyro.sample("sh", dist.Categorical(torch.ones(nT)))
        cl = pyro.sample("cl", dist.Categorical(torch.ones(2)))
        pyro.factor("obs", score[cl, st, tt, sh])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["cl"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    return {classes[int(i)]: p for i, p in zip(sup.tolist(), pr.tolist())}


