# Speaker: utterance posterior given (state, valence, arousal, goal), inferred.
def speaker_logprobs(st_idx, val, ar, goal):
    gv = goal_value(goal, st_idx, val, ar)
    key = (gv, goal)
    if key in spk_cache:
        return spk_cache[key]
    l0 = {u: literal_listener(u, goal) for u in range(len(utterances))}

    @pyro.infer.config_enumerate
    def model():
        u = pyro.sample("u", dist.Categorical(torch.ones(len(utterances))))
        sc = torch.tensor([math.log(l0[uu].get(gv, 0.0)) if l0[uu].get(gv, 0.0) > 0 else NEG
                           for uu in range(len(utterances))])
        pyro.factor("sc", 1.0 * sc[u])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["u"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    res = {int(i): p for i, p in zip(sup.tolist(), pr.tolist())}
    spk_cache[key] = res
    return res


