    p = speaker(scope, state, qud).get(utterance, 0.0)
    return math.log(p) if p > 0 else float("-inf")


# ---- Pragmatic listener L1: posterior over state given utterance ----
L1_cache = {}


def pragmatic_listener(utterance):
    if utterance in L1_cache:
        return L1_cache[utterance]
    # finished speaker scores for every (state, scope, qud), evaluated up front
    tbl = torch.full((len(states), len(scopes), len(QUDs)), float("-inf"))
    for si, st in enumerate(states):
        for sci, scp in enumerate(scopes):
            for qi, qd in enumerate(QUDs):
                tbl[si, sci, qi] = speaker_score(scp, st, qd, utterance)

    @pyro.infer.config_enumerate
    def model():
        s = pyro.sample("L1_state", dist.Categorical(logits=state_logits))
        sc = pyro.sample("L1_scope", dist.Categorical(logits=scope_logits))
        q = pyro.sample("L1_qud", dist.Categorical(logits=qud_logits))
        pyro.factor("L1_obs", tbl[s, sc, q])
        return s

    post = enum_marginal(model, "L1_state")
    L1_cache[utterance] = {states[i]: p for i, p in post.items()}
    return L1_cache[utterance]


def pragmatic_listener_score(utterance, state):
    p = pragmatic_listener(utterance).get(state, 0.0)
    return math.log(p) if p > 0 else float("-inf")


# ---- Pragmatic speaker S2: distribution over utterances given state ----
