    def model():
        u = pyro.sample("S2_utt", dist.Categorical(logits=utt_logits))
        pyro.factor("S2_f", sc[u])
        return u

    post = enum_marginal(model, "S2_utt")
    return {utterances[i]: p for i, p in post.items()}


