shirt_colors = ["red shirt", "blue shirt", "green shirt", "yellow shirt"]


def make_single_context(filler_fruit, n_with_apples, n_total):
    out = []
    for i in range(n_total):
        if i < n_with_apples:
            out.append({"fruit": "apples", "shirt": shirt_colors[i]})
        else:
            out.append({"fruit": filler_fruit, "shirt": shirt_colors[i]})
    return out


def make_quadrant_contexts(filler_fruit):
    return [make_single_context(filler_fruit, 3 - n, n) for n in range(4)]


contexts_type_a = make_quadrant_contexts(False)
contexts_type_b = make_quadrant_contexts("oranges")

referent_nonexistence = {"fruit": False, "shirt": "yellow shirt"}
referent_alternative = {"fruit": "oranges", "shirt": "yellow shirt"}


def is_negation(u):
    return u in ("no apples", "no oranges")


utterances = [
    "apples", "oranges", "no apples", "no oranges",
    "red shirt", "blue shirt", "green shirt", "yellow shirt",
]


def utt_cost(u):
    n_words = len(u.split(" "))
    return (n_words - 1) * 1.0


utt_probs_raw = [math.exp(-utt_cost(u)) for u in utterances]


def meaning(u, obj):
    base = u[3:] if is_negation(u) else u
    ref_prop = "shirt" if "shirt" in base else "fruit"
    obj_val = 1 if obj[ref_prop] == base else -1
    neg_val = -1 if is_negation(u) else 1
    return 0.999 if (neg_val * obj_val) == 1 else 0.001


def qud_apples(obj):
    return obj["fruit"] == "apples"


def qud_which_fruit(obj):
    return obj["fruit"]


qud_fns = {"apples?": qud_apples, "which fruit?": qud_which_fruit}
alpha = 1.0

NEG = torch.tensor(float("-inf"))
ZERO = torch.tensor(0.0)


def literal_listener(utterance, qud, all_objects):
    n = len(all_objects)
    qfn = qud_fns[qud]
    if n == 1:
        # A single-object context has no other hypothesis to draw from: Pyro's
        # enumeration machinery needs >=2 support elements to allocate an
        # enumeration dim, but with one object Bayes' rule is a no-op anyway --
        # the listener's belief is a point mass on that object's QUD value.
        return {qfn(all_objects[0]): 1.0}
    p_match = torch.tensor([meaning(utterance, o) for o in all_objects])

    @pyro.infer.config_enumerate
    def model():
        idx = pyro.sample("obj0", dist.Categorical(torch.ones(n)))
        coin = pyro.sample("coin0", dist.Bernoulli(p_match[idx]))
        pyro.factor("cond0", torch.where(coin > 0, ZERO, NEG))
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)["obj0"]
    sup = marg.enumerate_support()
    pr = marg.log_prob(sup).exp()
    out = {}
    for i, p in zip(sup.tolist(), pr.tolist()):
        q = qfn(all_objects[int(i)])
        out[q] = out.get(q, 0.0) + p
    return out


def speaker(obj, context, qud):
    all_objects = context + [obj]
    utt_prior_t = torch.tensor(utt_probs_raw)
    p_match_target = torch.tensor([meaning(u, obj) for u in utterances])
    qfn = qud_fns[qud]
    target_q = qfn(obj)
    l0_scores = []
    for u in utterances:
        l0 = literal_listener(u, qud, all_objects)
        p = l0.get(target_q, 0.0)
        l0_scores.append(math.log(p) if p > 0 else float("-inf"))
    l0_scores_t = torch.tensor(l0_scores)

    @pyro.infer.config_enumerate
    def model():
        u = pyro.sample("utt0", dist.Categorical(utt_prior_t))
        coin = pyro.sample("coin1", dist.Bernoulli(p_match_target[u]))
        pyro.factor("filt", torch.where(coin > 0, ZERO, NEG))
        pyro.factor("inform", alpha * l0_scores_t[u])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)["utt0"]
    sup = marg.enumerate_support()
    pr = marg.log_prob(sup).exp()
    return {utterances[int(i)]: p for i, p in zip(sup.tolist(), pr.tolist())}


def no_apples_probs(referent, contexts, qud):
    return [speaker(referent, ctx, qud).get("no apples", 0.0) for ctx in contexts]


