# Literal listener: uniform prior over states, factor(meaning(utt, state)) added as
# a log-weight. Inference is exact enumeration via Pyro's compute_marginals.
_L0_cache = {}
def literalListener(utt):
    if utt in _L0_cache:
        return _L0_cache[utt]
    _mvals = torch.tensor([meaning(utt, s) for s in states])
    @pyro.infer.config_enumerate
    def m():
        idx = pyro.sample("state", dist.Categorical(torch.ones(len(states))))
        pyro.factor("sem", _mvals[idx])
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(m, lambda: None)
    _L0_cache[utt] = marg["state"]
    return _L0_cache[utt]

