    sidx = states.index(state)
    L0s = [literalListener(u) for u in utterances]
    _scores = torch.tensor([
        alpha * L0s[i].log_prob(torch.tensor(sidx)).item() - costWeight * cost[utterances[i]]
        for i in range(len(utterances))
    ])
    @pyro.infer.config_enumerate
    def m():
        uidx = pyro.sample("utt", dist.Categorical(torch.ones(len(utterances))))
        pyro.factor("util", _scores[uidx])
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(m, lambda: None)
    return marg["utt"]

