# Frank & Goodman (2012) RSA with a preference-dependent object prior.
# Each RSA level is a separate, completely-finished Pyro discrete enumeration
# (config_enumerate + TraceEnum_ELBO.compute_marginals). Lower levels are fully
# computed and memoized BEFORE any higher level runs, so no inference ever runs
# inside another inference's active enumeration. Each level's single latent has
# a site name unique across levels (o0 / u1 / o2), avoiding site collisions.

objects = ["blue square", "blue circle", "green square"]
object_tokens = [["blue", "square"], ["blue", "circle"], ["green", "square"]]
utterances = ["blue", "green", "square", "circle"]
