utt_logits = torch.zeros(len(utterances))      # speaker draws utterances uniformly
l0_state_logits = torch.zeros(len(objects))    # L0 object prior is uniform


def meaning(utterance, obj_idx):
    return utterance in object_tokens[obj_idx]


def marginal_dict(model, site, support):
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(
        model, lambda: None
    )[site]
    sup = marg.enumerate_support()
    probs = marg.log_prob(sup).exp()
    out = {}
    for i in range(sup.shape[0]):
        out[support[int(sup[i].item())]] = float(probs[i].item())
    return out


def logscore(d, key):
    p = d.get(key, 0.0)
    return math.log(p) if p > 0 else float("-inf")


# ---- Literal listener L0: infer object given utterance (uniform object prior) ----
L0_cache = {}


def literal_listener(utterance):
    if utterance in L0_cache:
        return L0_cache[utterance]

    @pyro.infer.config_enumerate
    def model():
        o = pyro.sample("o0", dist.Categorical(logits=l0_state_logits))
        ok = torch.tensor([meaning(utterance, i) for i in range(len(objects))])
        pyro.factor("ev", torch.where(ok[o], torch.tensor(0.0), torch.tensor(float("-inf"))))

    L0_cache[utterance] = marginal_dict(model, "o0", objects)
    return L0_cache[utterance]


# ---- Speaker: infer utterance given object ----
S_cache = {}


def speaker(obj):
    if obj in S_cache:
        return S_cache[obj]
    # speaker scores by L0.score(obj); pre-warm all L0 marginals first.
    sc = torch.tensor([alpha * logscore(literal_listener(u), obj) for u in utterances])

    @pyro.infer.config_enumerate
    def model():
        u = pyro.sample("u1", dist.Categorical(logits=utt_logits))
        pyro.factor("f", sc[u])

    S_cache[obj] = marginal_dict(model, "u1", utterances)
    return S_cache[obj]


