n_thetas = len(theta_pairs)  # 28

NEG = -1e30
ZERO = torch.tensor(0.0)


def theta_bins(theta):
    half = theta / 2.0
    return [0.0, half, theta]


def meaning_fn(values, bins):
    # coverage: each of the len(bins)-1 sub-intervals (bins[i], bins[i+1]] has
    # at least one value in it
    for i in range(len(bins) - 1):
        if not any(bins[i] < v <= bins[i + 1] for v in values):
            return False
    return True


def meaning(utterance, theta_r, theta_t, values):
    if utterance == "prog":
        return meaning_fn(values, theta_bins(theta_r))
    if utterance == "impf":
        return meaning_fn(values, theta_bins(theta_t))
    return True


# --- literal listener: real Pyro inference over the 31 nonempty world
# states, one per (utterance, thetaR, thetaT), memoized. ---
_ll_cache = {}


def literal_listener(utterance, theta_r, theta_t):
    key = (utterance, theta_r, theta_t)
    if key in _ll_cache:
        return _ll_cache[key]
    truth = torch.tensor([
        1.0 if meaning(utterance, theta_r, theta_t, subset_values(f)) else 0.0
        for f in subset_flags
    ])

    @pyro.infer.config_enumerate
    def model():
        s = pyro.sample("s", dist.Categorical(torch.ones(n_states)))
        pyro.factor("cond", torch.where(truth[s] > 0, ZERO, torch.tensor(NEG)))
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["s"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    out = [0.0] * n_states
    for i, p in zip(sup.tolist(), pr.tolist()):
        out[int(i)] = p
    _ll_cache[key] = out
    return out


