# (state, thetaR, thetaT) triple; cost-weighted prior + literal-listener
# reweighting (memoized listener lookups). ---
def speaker_dist(state_idx, theta_r, theta_t):
    scores = []
    for u in utterances:
        p = literal_listener(u, theta_r, theta_t)[state_idx]
        scores.append(-cost[u] + (math.log(p) if p > 0 else NEG))
    scores_t = torch.tensor(scores)

    @pyro.infer.config_enumerate
    def model():
        u = pyro.sample("u", dist.Categorical(torch.ones(3)))
        pyro.factor("sc", scores_t[u])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["u"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    return {utterances[int(i)]: p for i, p in zip(sup.tolist(), pr.tolist())}


