    return state == 0  # none


def qud_fn(qud, state):
    if qud == "all?":
        return state == 3
    return state > 0  # any?


def marginal_dict(model, site, support):
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(
        model, lambda: None
    )[site]
    sup = marg.enumerate_support()
    probs = marg.log_prob(sup).exp()
    out = {}
    for i in range(sup.shape[0]):
        out[support[int(sup[i].item())]] = float(probs[i].item())
    return out


def logscore(d, key):
    p = d.get(key, 0.0)
    return math.log(p) if p > 0 else float("-inf")


# ---- Literal listener L0: infer qudFn(qud,state) given (utt, qud) ----
L0_cache = {}


def literal_listener(utt, qud):
    key = (utt, qud)
    if key in L0_cache:
        return L0_cache[key]
    qspace = [False, True]  # support over the QUD projection value

    @pyro.infer.config_enumerate
    def model():
        s = pyro.sample("s0", dist.Categorical(logits=state_logits))
        ok = torch.tensor([literal_meaning(utt, st) for st in states])
        pyro.factor("ev", torch.where(ok[s], torch.tensor(0.0), torch.tensor(float("-inf"))))
        qidx = torch.tensor([1 if qud_fn(qud, st) else 0 for st in states])
        # deterministic projection of the latent state to its QUD value,
        # realized as an enumerated site pinned to qudFn(qud,state).
        x = pyro.sample("qval", dist.Categorical(logits=torch.zeros(2)))
        pyro.factor("proj", torch.where(x == qidx[s], torch.tensor(0.0), torch.tensor(float("-inf"))))

    L0_cache[key] = marginal_dict(model, "qval", qspace)
    return L0_cache[key]


# ---- Speaker: infer utterance given (state, qud) ----
S_cache = {}


def speaker(state, qud):
    key = (state, qud)
    if key in S_cache:
        return S_cache[key]
    qval = qud_fn(qud, state)
    # speaker scores by L0.score(qudFn(qud,state)); pre-warm L0 first.
    sc = torch.tensor([alpha * logscore(literal_listener(u, qud), qval) for u in utterances])

    @pyro.infer.config_enumerate
    def model():
        u = pyro.sample("u1", dist.Categorical(logits=utt_logits))
        pyro.factor("f", sc[u])

    S_cache[key] = marginal_dict(model, "u1", utterances)
    return S_cache[key]


