def pragmatic_listener(utt, qud):
    # Fully compute & memoize all speaker marginals we need BEFORE outer run.
    sc = torch.tensor([logscore(speaker(st, qud), utt) for st in states])

    @pyro.infer.config_enumerate
    def model():
        s = pyro.sample("s2", dist.Categorical(logits=state_logits))
        pyro.factor("obs", sc[s])

    return marginal_dict(model, "s2", states)


