    return math.log(report[event])


def quadratic_score(report, event):
    squares = sum(report[x] ** 2 for x in outcomes)
    return 2 * report[event] - squares


def linear_score(report, event):
    return report[event]


# The agent's true belief and the four candidate reports are given constants
# (not inferred quantities), so the per-candidate expected score under the
# belief distribution is a direct expectation -- exactly what WebPPL's
# `expectation(Infer(...))` over a non-conditioned sample computes.
def expected_score(score_fn, report):
    return sum(belief[e] * score_fn(report, e) for e in outcomes)


# The agent: real inference over which candidate report is chosen, softmax-
# weighted by its expected score under the given scoring rule.
def agent(score_fn):
    scores = torch.tensor([
        alpha * expected_score(score_fn, candidate_reports[i]) for i in range(4)
    ])

    @pyro.infer.config_enumerate
    def model():
        idx = pyro.sample("agent_idx", dist.Categorical(torch.ones(4)))
        pyro.factor("agent_f", scores[idx])

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)
    m = marg["agent_idx"]
    sup = m.enumerate_support()
    pr = m.log_prob(sup).exp()
    return {int(i) + 1: float(p) for i, p in zip(sup.tolist(), pr.tolist())}


