def meaning(utt, world):
    if utt == "Some":
        return world > 0
    if utt == "All":
        return world == numObjs
    return world == 0


def binomial_marbles(theta):
    d = dist.Binomial(total_count=numObjs, probs=torch.tensor(theta))
    return torch.stack([d.log_prob(torch.tensor(float(x))).exp() for x in range(numObjs + 1)])


speaker_optimality = 1.0
NEG = torch.tensor(float("-inf"))
ZERO = torch.tensor(0.0)

# regime is a bool: True = wonky (theta=0.5), False = normal (theta=0.99).
priors = {
    True: binomial_marbles(0.5),
    False: binomial_marbles(0.99),
}

L0_cache = {}


def literal_listener(utterance, regime):
    # Cache MUST be keyed by (utterance, regime) -- the two regimes have different
    # priors, so a literal listener computed under one regime cannot be reused
    # under the other even for the same utterance.
    key = (utterance, regime)
    if key in L0_cache:
        return L0_cache[key]
    prior = priors[regime]
    ok = torch.tensor([1.0 if meaning(utterance, w) else 0.0 for w in range(numObjs + 1)])

    @pyro.infer.config_enumerate
    def model():
        w = pyro.sample("world0", dist.Categorical(prior))
        pyro.factor("cond0", torch.where(ok[w] > 0, ZERO, NEG))
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)["world0"]
    sup = marg.enumerate_support()
    pr = marg.log_prob(sup).exp()
    out = {int(i): p for i, p in zip(sup.tolist(), pr.tolist())}
    L0_cache[key] = out
    return out


S_cache = {}


def speaker(world, regime):
    # Same regime-collision hazard as literal_listener: world values (0..15)
    # recur across both regimes, so the cache key must carry the regime too.
    key = (world, regime)
    if key in S_cache:
        return S_cache[key]
    l0s = [literal_listener(u, regime) for u in utterances]
    sc = torch.tensor([
        (math.log(l0s[j].get(world, 0.0)) if l0s[j].get(world, 0.0) > 0 else float("-inf"))
        for j in range(len(utterances))
    ])

    @pyro.infer.config_enumerate
    def model():
        u = pyro.sample("utt1", dist.Categorical(torch.ones(len(utterances))))
        pyro.factor("f1", speaker_optimality * sc[u])
        return None

    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(model, lambda: None)["utt1"]
    sup = marg.enumerate_support()
    pr = marg.log_prob(sup).exp()
    out = {utterances[int(i)]: p for i, p in zip(sup.tolist(), pr.tolist())}
    S_cache[key] = out
    return out


