# RSA (Rational Speech Acts), three levels, faithful to the WebPPL reference.
# Each level is genuine Pyro enumeration inference over a single-sample model;
# inner-level distributions feed the outer level's pyro.factor via their log-prob.

objects = [
    {"shape": "square", "color": "blue"},
    {"shape": "circle", "color": "blue"},
    {"shape": "square", "color": "green"},
]
utterances = ["blue", "green", "square", "circle"]


def meaning(utterance, obj):
    if utterance == "blue" or utterance == "green":
        return utterance == obj["color"]
    if utterance == "circle" or utterance == "square":
        return utterance == obj["shape"]
    return True


def enum_dist(model, values):
    # Run exact enumeration over the single latent site 'x' (an index into
    # `values`) and return {value_index: probability} from the marginal.
    marg = pyro.infer.TraceEnum_ELBO(max_plate_nesting=0).compute_marginals(
        model, lambda: None
    )["x"]
    sup = marg.enumerate_support()
    probs = marg.log_prob(sup).exp()
    out = {}
    for s, p in zip(sup.tolist(), probs.tolist()):
        out[int(s)] = p
    return out


def literal_listener(utterance):
    # uniform prior over objects, condition on the utterance being true
    @pyro.infer.config_enumerate
    def model():
        x = pyro.sample(
            "x", dist.Categorical(torch.ones(len(objects)))
        )
        truths = torch.tensor(
            [1.0 if meaning(utterance, o) else 0.0 for o in objects]
        )
        ev = torch.log(truths)[x]
        pyro.factor("ev", ev)
        return x

    return enum_dist(model, objects)


def speaker(obj_idx, alpha):
    # cache literal-listener log-scores of obj_idx under each utterance
    ll_scores = []
    for u in utterances:
        d = literal_listener(u)
        p = d.get(obj_idx, 0.0)
        ll_scores.append(math.log(p) if p > 0 else float("-inf"))
    ll_scores = torch.tensor(ll_scores)

    @pyro.infer.config_enumerate
    def model():
        x = pyro.sample("x", dist.Categorical(torch.ones(len(utterances))))
        pyro.factor("ev", alpha * ll_scores[x])
        return x

    return enum_dist(model, utterances)


def pragmatic_listener(utterance, alpha):
    # uniform prior over objects, observe the speaker uttering `utterance`
    u_idx = utterances.index(utterance)
    # speaker(obj, alpha) log-prob of the heard utterance, per object
    sp_scores = []
    for i in range(len(objects)):
        d = speaker(i, alpha)
        p = d.get(u_idx, 0.0)
        sp_scores.append(math.log(p) if p > 0 else float("-inf"))
    sp_scores = torch.tensor(sp_scores)

    @pyro.infer.config_enumerate
    def model():
        x = pyro.sample("x", dist.Categorical(torch.ones(len(objects))))
        pyro.factor("ev", sp_scores[x])
        return x

    d = enum_dist(model, objects)
    return {i: d.get(i, 0.0) for i in range(len(objects))}


def as_record_dist(idx_dist):
    out = {}
    for i, o in enumerate(objects):
        out[json.dumps(o, sort_keys=True)] = idx_dist.get(i, 0.0)
    return out


